  if(delta<0||(temperature>0&&rnd.real()<exp(-double(delta)/temperature))){codes[gx]=tx;freq[gx]=fx;score[gx]=sx;if(gx!=gy){codes[gy]=ty;freq[gy]=fy;score[gy]=sy;}if(inv)flip[x]^=1;else{swap(col[x],col[y]);swap(flip[x],flip[y]);}now+=delta;if(now<best){best=now;bc=col;bf=flip;}return true;}return false;
