 for(iter=0;iter<STEPS;iter++){if((iter&127)==0){elapsed=double(clock()-ast)/CLOCKS_PER_SEC;if(elapsed>BUDGET)break;double progress=max(elapsed/BUDGET,double(iter)/STEPS);temp=.04*pow(.008,progress);}int x=rnd.pick(64),y=rnd.pick(64);bool inv=rnd.pick(5)==0;if(!inv&&x==y)continue;attempt(x,y,inv,temp);}
 col=bc;flip=bf;rebuild();now=accumulate(score.begin(),score.end(),0.f);best=now;
 // Deterministic coordinate-descent finishing pass.
 for(int pass=0;pass<2;pass++){for(int x=0;x<64;x++){attempt(x,x,true,0);for(int y=x+1;y<64;y++)attempt(x,y,false,0);}}
 col=bc;flip=bf;rebuild();
 cerr<<"SA="<<iter<<" CPU="<<double(clock())/CLOCKS_PER_SEC<<endl; Graph g;cerr<<"GraphCPU="<<double(clock())/CLOCKS_PER_SEC<<endl;vector<unique_ptr<Policy>>pol;for(int z=0;z<8;z++)pol.emplace_back(make_unique<Policy>(g,vector<int>(freq[z].begin(),freq[z].end())));
 vector<string>design(192,string(64,'.'));for(int z=0;z<8;z++)for(int k=0;k<9;k++)for(int j=0;j<8;j++){char c=PAT[k][j];if(c!='.')design[9*z+k][col[8*z+j]]='0'+((c-'0')^flip[8*z+j]);}for(auto&s:design)cout<<s<<'\n';cout.flush();
 int state[8]{};long total=0;
 int hist[8][9]{},allhist[8][9]{};
 auto record=[&](int s,int h[8][9]){auto&pm=g.perm[s];int p7=find(pm.begin(),pm.end(),7)-pm.begin(),p8=find(pm.begin(),pm.end(),8)-pm.begin();p7-=p8<p7;h[p7][p8]++;};
 for(int r=0;r<R;r++){int a;if(!(cin>>a)||a<0||a>=P)return 0;vector<pair<int,int>>ops;for(int z=0;z<8;z++){int t=codes[z][a];while(g.display[state[z]]!=t){auto e=pol[z]->step(t,state[z]);ops.emplace_back(9*z+e.paper,9*z+e.pos);state[z]=e.next;record(state[z],allhist);}record(state[z],hist);}
  if(r==R-1){for(int x=0;x<8;x++){for(int y=0;y<9;y++)cerr<<hist[x][y]<<",";cerr<<"\n";}cerr<<"MOVES\n";for(int x=0;x<8;x++){for(int y=0;y<9;y++)cerr<<allhist[x][y]<<",";cerr<<"\n";}} if(r==R-1)cerr<<"FinishCPU="<<double(clock())/CLOCKS_PER_SEC<<endl; total+=ops.size();cout<<ops.size()<<'\n';for(auto[k,d]:ops)cout<<k<<' '<<d<<'\n';cout.flush();
 }
 
